// A bilingual entry point; legacy workshop pages are explicitly labelled Spanish.
(()=>{if(window.top!==window.self)return;const script=document.currentScript,root=new URL('.',script.src),bar=document.createElement('aside');bar.setAttribute('aria-label','Courses / Cursos · Language / Idioma');bar.style.cssText='padding:14px 5%;display:flex;gap:18px;flex-wrap:wrap;align-items:center;background:#20382e;color:#f4f3eb;font:14px/1.5 sans-serif;';const label=document.createElement('strong');label.textContent='Workshop Academy · Mecánica / Electronics / Hidráulica / Pneumatics';bar.append(label);for(const [lang,title]of [['es','Cursos en español →'],['en','Courses in English →']]){const link=document.createElement('a');link.href=new URL('learn/index.html?lang='+lang,root);link.hreflang=lang;link.textContent=title;link.style.color='#d4e59a';bar.append(link);}document.body.prepend(bar);})();
